import type { SiteData, Trip } from "./types";

function fmt(n: number): string {
  return n.toLocaleString();
}

function renderTripItem(trip: Trip): string {
  const featured = trip.featured ? " featured" : "";
  const year = trip.start?.slice(0, 4) ?? "";
  const dest = trip.story_dest || trip.dest_label || "";
  const photos = trip.photo_count ? ` · ${trip.photo_count} photos` : "";
  return `
    <div class="trip-item${featured}" data-id="${trip.id}" data-year="${year}" data-dest="${dest}" style="color:${trip.color}">
      <div class="trip-swatch" style="background:${trip.color}"></div>
      <div>
        <div class="trip-name">${trip.name}</div>
        <div class="trip-meta">${trip.start} · ${trip.miles} mi · ${trip.stop_count} stops${photos}</div>
      </div>
    </div>`;
}

function renderTimeline(segments: SiteData["timeline"]): string {
  return segments
    .map(
      (seg) =>
        `<div class="tl-seg${seg.has_colorado ? " featured" : ""}" data-id="${seg.id}" data-year="${seg.start?.slice(0, 4) ?? ""}" title="${seg.name}" style="left:${seg.left_pct}%;width:${seg.width_pct}%;background:${seg.color}"></div>`,
    )
    .join("");
}

export function hydrateShell(data: SiteData): void {
  const { dashboard, trips, timeline } = data;
  const setText = (id: string, text: string) => {
    const el = document.getElementById(id);
    if (el) el.textContent = text;
  };

  setText("stat-trip-count", String(trips.length));
  setText("stat-total-miles", fmt(dashboard.total_miles));
  setText("panel-trip-count", String(dashboard.trip_count));
  setText("journey-open-badge", String(trips.length));
  setText("stat-places", String(dashboard.total_places ?? 0));
  setText("stat-photos", String(dashboard.total_photos ?? 0));
  setText("stat-days", String(dashboard.total_days ?? dashboard.trip_count));

  const splash = document.querySelector("#splash p");
  if (splash) {
    splash.textContent = `Miles become memories · ${trips.length} journeys · ${fmt(dashboard.total_miles)} miles`;
  }

  const panelSub = document.getElementById("panel-sub");
  if (panelSub) {
    panelSub.textContent = `${dashboard.trip_count} trips · ${fmt(dashboard.total_miles)} miles`;
  }

  const allMeta = document.querySelector('.trip-item[data-id="all"] .trip-meta');
  if (allMeta) {
    allMeta.textContent = `${trips.length} trips · ${fmt(dashboard.total_miles)} mi`;
  }

  const listMount = document.getElementById("trip-list-items");
  if (listMount) {
    const sorted = [...trips].sort((a, b) => (b.start || "").localeCompare(a.start || ""));
    listMount.innerHTML = sorted.map(renderTripItem).join("");
  }

  const years = [...new Set(trips.map((t) => t.start?.slice(0, 4)).filter(Boolean))].sort();
  const tlLabel = document.getElementById("timeline-label");
  if (tlLabel && years.length) {
    tlLabel.textContent = `Journey Timeline · ${years[0]} — ${years[years.length - 1]}`;
  }

  const track = document.getElementById("timeline-track");
  if (track) {
    const scrub = track.querySelector("#timeline-scrub");
    track.innerHTML = renderTimeline(timeline);
    if (scrub) track.appendChild(scrub);
    else {
      const div = document.createElement("div");
      div.className = "timeline-scrub";
      div.id = "timeline-scrub";
      div.style.left = "0%";
      track.appendChild(div);
    }
  }
}
